INSERT INTO "research_projects" VALUES(76,'finished','','','Design and Development of Researcher Capacity Building Curriculum for Higher Education Institutions and a Support System for Building R&D Strategies and Action Plans for Enterprises (Talent Mobility System) to Support Personnel Mobility for Research Capacity Development in the Industrial Sector (Talent Mobility Track 2)','การออกแบบและพัฒนาหลักสูตรการพัฒนาศักยภาพนักวิจัยของสถาบันอุดมศึกษา และระบบสนับสนุนการสร้างกลยุทธ์และแผนปฏิบัติการด้านการวิจัยและพัฒนาสำหรับสถานประกอบการ (Talent Mobility System) รองรับการเคลื่อนย้ายบุคลากร เพื่อพัฒนาศักยภาพการวิจัยในภาคอุตสาหกรรม (Talent Mobility Track 2)','Prof. Apichat Sopadang, Ph.D.','ศาสตราจารย์ ดร.อภิชาต โสภาแดง',NULL,'Assoc. Prof. Sakgasem Ramingwong, Ph.D.','รองศาสตราจารย์ ดร.ศักดิ์เกษม ระมิงค์วงศ์',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Asst. Prof. Salinee Santiteerakul, Ph.D.','ผู้ช่วยศาสตราจารย์ ดร.สาลินี สันติธีรากุล',NULL,'Miss Chalisa Naroon','นางสาวชาลิสา ณรุณ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The first phase of the Talent Mobility System development, covering the design of a 15-hour expert training curriculum (Track 2.1) and the development of the central support system website, talentmobility.in.th, including the public relations and application system, expert database, learning assessment system, and project monitoring and reporting system.','โครงการระยะแรกของการพัฒนาระบบ Talent Mobility System ครอบคลุมการออกแบบหลักสูตรอบรมผู้เชี่ยวชาญ 15 ชั่วโมง (Track 2.1) และพัฒนาเว็บไซต์ระบบสนับสนุนกลาง talentmobility.in.th ทั้งระบบประชาสัมพันธ์-รับสมัคร ฐานข้อมูลผู้เชี่ยวชาญ ระบบประเมินผลการเรียนรู้ และระบบรายงานผลติดตามโครงการ');
INSERT INTO "research_projects" VALUES(77,'finished','','','Design and Development of Researcher Capacity Building Curriculum for Higher Education Institutions and a Support System for Building R&D Strategies and Action Plans for Enterprises (Additional Phase)','การออกแบบและพัฒนาหลักสูตรการพัฒนาศักยภาพนักวิจัยของสถาบันอุดมศึกษาและระบบสนับสนุนการสร้างกลยุทธ์และแผนปฏิบัติการด้านการวิจัยและพัฒนาสำหรับสถานประกอบการ (เพิ่มเติม)','Prof. Apichat Sopadang, Ph.D.','ศาสตราจารย์ ดร.อภิชาต โสภาแดง',NULL,'Assoc. Prof. Sakgasem Ramingwong, Ph.D.','รองศาสตราจารย์ ดร.ศักดิ์เกษม ระมิงค์วงศ์',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Asst. Prof. Salinee Santiteerakul, Ph.D.','ผู้ช่วยศาสตราจารย์ ดร.สาลินี สันติธีรากุล',NULL,'Miss Chalisa Naroon','นางสาวชาลิสา ณรุณ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'An extension of the first phase, providing additional expert training for cohorts 4-6 (100 participants in total) and adding an "Enterprise" application and database function to the Talent Mobility System to more comprehensively support collaboration with the industrial sector.','ต่อยอดโครงการจากระยะแรก ด้วยการจัดอบรมผู้เชี่ยวชาญเพิ่มเติมรุ่นที่ 4–6 (รวม 100 คน) พร้อมทั้งเพิ่มฟังก์ชันระบบรับสมัครและฐานข้อมูล "สถานประกอบการ" เข้าสู่ระบบ Talent Mobility System เพื่อรองรับการทำงานร่วมกับภาคอุตสาหกรรมได้ครบวงจรยิ่งขึ้น');
INSERT INTO "research_projects" VALUES(78,'finished','','','Design and Development of Researcher Capacity Building Curriculum for Higher Education Institutions and a Support System for Building R&D Strategies and Action Plans for Enterprises (Additional Phase 2)','การออกแบบและพัฒนาหลักสูตรการพัฒนาศักยภาพนักวิจัยของสถาบันอุดมศึกษาและระบบสนับสนุนการสร้างกลยุทธ์และแผนปฏิบัติการด้านการวิจัยและพัฒนาสำหรับสถานประกอบการ (เพิ่มเติม) ครั้งที่ 2','Prof. Apichat Sopadang, Ph.D.','ศาสตราจารย์ ดร.อภิชาต โสภาแดง',NULL,'Assoc. Prof. Sakgasem Ramingwong, Ph.D.','รองศาสตราจารย์ ดร.ศักดิ์เกษม ระมิงค์วงศ์',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Asst. Prof. Salinee Santiteerakul, Ph.D.','ผู้ช่วยศาสตราจารย์ ดร.สาลินี สันติธีรากุล',NULL,'Miss Chalisa Naroon','นางสาวชาลิสา ณรุณ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Expansion of the Talent Mobility System to cover Track 1 (technology deployment) and Track 3 (R&D activity stimulation), in addition to the existing Track 2 support, together with expert training for cohorts 7-10 (120 participants in total) and knowledge-sharing seminars to review the curriculum and the system with past experts.','ขยายระบบ Talent Mobility System ให้ครอบคลุม Track 1 (ติดตั้งเทคโนโลยี) และ Track 3 (กระตุ้นกิจกรรม R&D) เพิ่มเติมจากเดิมที่รองรับเฉพาะ Track 2 พร้อมจัดอบรมผู้เชี่ยวชาญรุ่นที่ 7–10 (รวม 120 คน) และจัดเวทีสัมมนาแลกเปลี่ยนเรียนรู้เพื่อทบทวนหลักสูตรและระบบร่วมกับผู้เชี่ยวชาญที่ผ่านมา');
INSERT INTO "research_projects" VALUES(79,'ongoing','','','Enhancing Personnel Mobility to Strengthen Industrial Competitiveness and Improving the Architectural Efficiency of the Supporting Information System','การยกระดับการเคลื่อนย้ายบุคลากรเพื่อพัฒนาขีดความสามารถการแข่งขันในภาคอุตสาหกรรมและการเพิ่มประสิทธิภาพเชิงสถาปัตยกรรมของระบบสารสนเทศสนับสนุน','Professor Dr. Apichat Sopadang','ศาสตราจารย์ ดร.อภิชาต โสภาแดง',NULL,'Associate Professor Dr. Sakgasem Ramingwong','รองศาสตราจารย์ ดร.ศักดิ์เกษม ระมิงค์วงศ์',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Assistant Professor Dr. Salinee Santiteerakul','ผู้ช่วยศาสตราจารย์ ดร.สาลินี สันติธีรากุล',NULL,'Miss Chalisa Naroon','นางสาวชาลิสา ณรุณ',NULL,'','',NULL,'12 months (25 June 2026 - 24 June 2027)','12 เดือน (25 มิถุนายน 2569 - 24 มิถุนายน 2570)','','','','','','',NULL,NULL,'','',NULL,NULL,'','A digital platform supporting the mobility of research personnel from higher education institutions into industry to strengthen industrial research capability (Talent Mobility), supported by the Office of the Permanent Secretary, MHESI. Developed continuously through several phases since 2023, the platform covers expert training curriculum design (Track 2.1), R&D strategy formulation for enterprises (Track 2.2), and most recently expansion to support Track 1 (technology deployment) and Track 3 (stimulation of R&D activity). Delivered through talentmobility.in.th, the system covers public relations, application intake, expert and enterprise databases, assessment, and project management and monitoring. To date more than 375 experts have registered and more than 20 projects have been undertaken with enterprises. The current phase focuses on maintaining system stability and continuous availability.','แพลตฟอร์มดิจิทัลสนับสนุนการเคลื่อนย้ายบุคลากรวิจัยจากสถาบันอุดมศึกษาไปช่วยพัฒนาศักยภาพการวิจัยให้ภาคอุตสาหกรรม (Talent Mobility) ภายใต้การสนับสนุนของ สป.อว. พัฒนาต่อเนื่องมาหลายระยะตั้งแต่ปี 2566 จนถึงปัจจุบัน ครอบคลุมทั้งการออกแบบหลักสูตรอบรมผู้เชี่ยวชาญ (Track 2.1) การสร้างกลยุทธ์วิจัยและพัฒนาให้สถานประกอบการ (Track 2.2) และล่าสุดขยายผลรองรับ Track 1 (ติดตั้งเทคโนโลยี) และ Track 3 (กระตุ้นกิจกรรม R&D) ระบบให้บริการผ่านเว็บไซต์ talentmobility.in.th ครอบคลุมงานประชาสัมพันธ์ รับสมัคร ฐานข้อมูลผู้เชี่ยวชาญและสถานประกอบการ ระบบประเมินผล และระบบติดตามบริหารโครงการ ปัจจุบันมีผู้เชี่ยวชาญขึ้นทะเบียนแล้วกว่า 375 คน และดำเนินโครงการร่วมกับสถานประกอบการไปแล้วกว่า 20 โครงการ โดยเฟสล่าสุดมุ่งเน้นการดูแลรักษาระบบให้มีเสถียรภาพและพร้อมใช้งานต่อเนื่อง');
INSERT INTO "research_projects" VALUES(80,'ongoing','','','Platform for Preparing Smart Geothermal Cooling Systems and Developing Supply Chain Resilience for Cold Storage Warehouse Infrastructure and Cold-Chain Logistics in the Thai Seafood Industry','โครงการแพลตฟอร์มเตรียมความพร้อมระบบทำความเย็นอัจฉริยะด้วยพลังงานใต้ดิน และการพัฒนาระบบ Supply Chain Resilience สำหรับโครงสร้างพื้นฐานคลังสินค้าห้องเย็นและ Cold-Chain Logistics ในอุตสาหกรรมอาหารทะเลของไทย','Associate Professor Dr. Poti Chaopaisarn','รองศาสตราจารย์ ดร. โพธิ จ้าวไพศาล',NULL,'','',NULL,'','',NULL,'','',NULL,'Professor of Practice Dr. Sate Sampattagul
